{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "A high-transfer human absolute bioavailability study reported only 4% (range 1–9%) oral bioavailability for a polar nucleoside-like analogue, directly below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Tetrahydrouridine, a polar nucleoside analogue, had 4.1% oral bioavailability in human pilot studies, supporting low F for this class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Gemcitabine, a high-transfer nucleoside analogue, has approximately 10% oral bioavailability in humans, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "The ribonucleoside analogue R1479 had estimated absolute oral bioavailability of 6–18% in humans, below the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Levovirin, a highly polar nucleoside, showed about 10% or less oral bioavailability in humans due to very low permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "ATP, a highly polar phosphorylated molecule, had very low estimated oral bioavailability (3.2 ± 0.6%) when given orally, illustrating the barrier for phosphate-containing polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Phlorizin, a glycosylated polar molecule, was limited by poor/low oral bioavailability in humans, supporting low F for large polar scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A high-transfer small nucleoside analogue (didanosine) reached 40–50% absolute oral bioavailability in adults, a counterexample showing that some small polar nucleosides can exceed the threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly polar corrinoid with a phosphate-ribose-dimethylbenzimidazole tail and multiple amide side chains, far more complex than the small nucleosides in the evidence set. The overwhelming majority of high-transfer human oral bioavailability measurements are below 20% (4%, 4.1%, ~10%, 6–18%, 3–15%), and the one high-F example (didanosine, 40–50%) is a much smaller nucleoside whose absorption mechanism does not transfer to the query's size and polarity. Therefore, absolute oral bioavailability is predicted to be low (<20%).",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query corrinoid.",
    "The only high-F analogue (didanosine) is much smaller and lacks the corrin macrocycle and phosphate, limiting its mechanistic relevance to the query.",
    "Potential active uptake mechanisms for B12-like corrinoids (e.g., intrinsic factor, cubilin) are not captured by the analogue evidence and could theoretically alter F, though they are saturable and generally do not produce high absolute oral bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

